  const guideStaticTranslations={
    overviewEyebrow:['AZ ELSŐ LÉPÉSTŐL A LEGENDÁIG','FROM FIRST STEPS TO LEGEND'],
    overviewTitle:['Találd meg a saját utad.','Find your own path.'],
    overviewSubtitle:['Minden, ami a kezdetekhez kell. Lépésről lépésre, érthetően.','Everything you need to get started. One clear step at a time.'],
    topicCharacter:['Karakteralkotás','Character creation'],
    topicCharacterCopy:['Válassz királyságot és találd meg a hozzád illő kasztot.','Choose a kingdom and find the class that suits you.'],
    topicCharacterLink:['Megalkotom a hősöm','Create my hero'],
    topicSteps:['Első lépések','First steps'],
    topicStepsCopy:['A falutól az első expedícióig. Így indulj el a kalandodon.','From the village to your first expedition. Start your adventure here.'],
    topicStepsLink:['Útnak indulok','Set out'],
    topicDaily:['Napi rutin','Daily routine'],
    topicDailyCopy:['Kis lépések, biztos fejlődés. Hozd ki a legtöbbet a napodból.','Small steps, steady progress. Make the most of your day.'],
    topicDailyLink:['Megnézem a teendőket','View my tasks'],
    topicProgress:['Fejlődés és felszerelés','Progress and equipment'],
    topicProgressCopy:['Erősebb hős, jobb felszerelés. Ismerd meg a fejlődés alapjait.','A stronger hero and better gear. Learn the basics of progression.'],
    topicProgressLink:['Erősebb leszek','Grow stronger'],
    introBefore:['A ','The game '],
    introAfter:[' kelet-ázsiai fantasyvilágban játszódó idle MMORPG. Hősöd akkor is vadászhat és fejlődhet, amikor te mással foglalkozol. Ez a kalauz segít átlátni az első döntéseket.',' is an idle MMORPG set in an East Asian fantasy world. Your hero can hunt and progress while you are busy with other things. This guide helps you make sense of your first decisions.'],
    aboutGuide:['A kalauzról','About this guide'],
    characterEyebrow:['01 / A HŐS SZÜLETÉSE','01 / THE BIRTH OF A HERO'],
    characterTitle:['Melyik útra lépsz?','Which path will you take?'],
    kingdomTitle:['Három zászló. Egy döntés.','Three banners. One choice.'],
    kingdomCopyBefore:['Bonghwa piros, Horang sárga, Miru kék királyság. A céhek azonos világban mindháromból fogadnak tagokat. A királyságot jelölő ','Bonghwa is the red kingdom, Horang the yellow, and Miru the blue. Guilds accept members from all three kingdoms within the same world. Choose a kingdom marked '],
    kingdomCopyAfter:[' jelzésű választással Pioneer pack jutalmat kapsz a kártyán megadott szinten.',' to receive a Pioneer pack at the level shown on the card.'],
    kingdomWarningTitle:['A királyság végleges választás.','Your kingdom choice is permanent.'],
    kingdomWarningCopy:['Amíg a hős még új, egyszer ingyen újrakezdhetsz. A barátokkal azonos világot válasszatok.','While your hero is still new, you can restart once for free. Choose the same world as your friends.'],
    kingdomBonghwa:['Az első lehetséges otthonod.','Your first possible home.'],
    kingdomHorang:['Egy másik zászló, közös kaland.','A different banner, an adventure together.'],
    kingdomMiru:['A harmadik út a világba.','A third path into the world.'],
    kingdomFinePrint:['A jelképek saját, hangulati illusztrációk, nem hivatalos címerek.','The symbols are original mood illustrations, not official heraldry.'],
    classesTitle:['Négy kaszt. Melyik illik hozzád?','Four classes. Which one suits you?'],
    classesCopy:['Jelölj ki két kasztot az összehasonlításhoz.','Select two classes to compare them.'],
    classesEyebrow:['NÉGY KÜLÖNBÖZŐ HARCI STÍLUS','FOUR DISTINCT COMBAT STYLES'],
    comparisonTitle:['Kasztok egymás mellett','Class comparison'],
    comparisonCount:['Válassz két kasztot','Choose two classes'],
    statsTitle:['Elsődleges statok','Primary stats'],
    statsStrength:['Warrior és Mage sebzése.','Warrior and Mage damage.'],
    statsDexterity:['Ninja sebzése, továbbá mindenkinek kritikus találat és kitérés.','Ninja damage, plus critical chance and evasion for every class.'],
    statsVitality:['HP és védelem.','HP and defence.'],
    statsIntelligence:['Shaman sebzése és a képességhez szükséges SP.','Shaman damage and the SP needed for skills.'],
    statsDetails:['Minden szinten statpontokat kapsz. A Suggested split elosztja őket a kasztodhoz; a Reset stats visszaadja a pontokat, és az első reset ingyenes. A két skill path közül korán választhatsz, értékeiket a Character → Skills mutatja.','You gain stat points at every level. Suggested split allocates them for your class; Reset stats refunds the points, and the first reset is free. You can choose between two skill paths early on; their effects are shown under Character → Skills.'],
    simpleTipTitle:['Tipp · Kezdd egyszerűen','Tip · Keep it simple'],
    simpleTip:['Használd a Suggested split lehetőséget, amíg kiismered a kasztod. A Warrior hivatalosan is kezdőbarát. A harc automatikus: elegendő SP-nél képesség, alacsony HP-nál potion következik — legyen nálad néhány.','Use Suggested split while you learn your class. Warrior is officially marked as beginner-friendly. Combat is automatic: skills trigger when you have enough SP, and a potion is used when HP is low—so keep a few with you.'],
    characterSheetEyebrow:['ISMERD MEG A KARAKTERLAPOT','GET TO KNOW YOUR CHARACTER SHEET'],
    characterSheetTitle:['A hős a részletekben él.','A hero comes to life in the details.'],
    characterSheetCopy:['A Character oldalon együtt látod a felszerelést, a statokat és a képességeket. A hivatalos képernyőképen egy Warrior karakterlapját nézheted meg.','The Character page brings your equipment, stats and skills together. The official screenshot shows a Warrior character sheet.'],
    characterSheetLink:['Felszerelés és Combat Power','Equipment and Combat Power'],
    stepsEyebrow:['02 / AZ ELSŐ KALAND','02 / THE FIRST ADVENTURE'],
    stepsTitle:['A faluból indul minden.','It all starts in the village.'],
    stepSaveTitle:['Mentsd el a vendéghősöd','Save your guest hero'],
    stepSave:['Egy érintéssel kezdhetsz vendégként. A későbbi e-mailes fiókmentés ingyenes és néhány Storm Coins jutalmat ad. Kódbeváltáshoz és chathez is szükséges.','You can start as a guest with one tap. Saving your hero to an email account later is free and awards a few Storm Coins. Saving is also required to redeem codes and use chat.'],
    stepSaveTip:['Tipp: a mobilos kezdőképernyőről indított játék külön böngészőnek számít. Előbb mentsd a hőst!','Tip: a game launched from your mobile home screen counts as a separate browser. Save your hero first!'],
    stepGilhwaTitle:['Kövesd Gilhwa útmutatását','Follow Gilhwa’s guidance'],
    stepGilhwa:['A leckék bármikor újraolvashatók a ? gomb mögötti Book of tips gyűjteményben. Ha valamit hosszan nyomva tartasz, Gilhwa elmagyarázza.','You can reread lessons at any time in the Book of tips behind the ? button. Long-press an element and Gilhwa will explain it.'],
    stepStoryTitle:['Captain Mugang és a történet','Captain Mugang and the story'],
    stepStory:['A felső tekercs mutatja az aktuális történeti parancsot. A fejezetek jutalmakat adnak, és a következő map bosshoz vezetnek. Ha nincs új történeti feladat, napi Captain’s contracts várnak.','The scroll at the top shows your current story order. Chapters award rewards and lead to the next map boss. When there is no new story task, daily Captain’s contracts are available.'],
    stepNpcsTitle:['Ismerd meg a falusi NPC-ket','Meet the village NPCs'],
    stepNpcs:['Dongsu: Daily Tasks. Gangdo: Blacksmith. Minah: potions; Kalbin: weapons; Taesan: armour; Jamul: materials. A felkiáltójel azt mutatja, hogy valaki vár rád.','Dongsu: Daily Tasks. Gangdo: Blacksmith. Minah: potions; Kalbin: weapons; Taesan: armour; Jamul: materials. An exclamation mark means someone is waiting for you.'],
    stepForayTitle:['Induljon az első Forays expedíció','Start your first Foray'],
    stepForay:['Hunt → Forays: válassz rövid, közepes vagy hosszú utat. A kártya mutatja az időt, energiát, jutalmat és a nehézséget: Easy, Even vagy Tough. Az állomások döntései után a stone guardians és egy választható láda vár.','Hunt → Forays: choose a short, medium or long trip. The card shows the time, energy cost, reward and difficulty: Easy, Even or Tough. After making your choices at each stop, you will face stone guardians and can choose a chest.'],
    stepForayTip:['Tipp: kezdd Easy úttal, és nézd meg a tooltipben a győzelmi esélyt.','Tip: start with an Easy trip and check your chance to win in the tooltip.'],
    stepHuntTitle:['Indíts Background Hunt vadászatot','Start a Background Hunt'],
    stepHunt:['Hunt → Hunting spots: válassz helyet az óránkénti XP és nyang alapján. A hős offline is gyűjt, de a zsák megtelésekor megáll. Gyűjtsd be rendszeresen; a Go here jobb helyre irányít.','Hunt → Hunting spots: choose a location based on XP and nyang per hour. Your hero collects loot while offline, but stops when the bag is full. Collect regularly; Go here directs you to a better spot.'],
    journeyTitle:['Nem kell mindent az első napon.','You do not need to do everything on day one.'],
    journeyCopy:['Gilhwa bemutatja az újonnan megnyíló rendszereket. Kezdésként a történet, a Forays és a Background Hunt legyen kéznél.','Gilhwa introduces systems as they unlock. To begin, focus on the story, Forays and Background Hunt.'],
    journeyLink:['Alakíts ki napi rutint','Build a daily routine'],
    todoTitle:['Today’s to-do · minden egy helyen','Today’s to-do · everything in one place'],
    todoCopy:['A HUD gombja Now, Later és Anytime csoportokban mutatja a teendőket. Go there: odaugrás. Claim all: több kész jutalom átvétele egyszerre.','The HUD button groups tasks into Now, Later and Anytime. Go there jumps to an activity. Claim all collects several completed rewards at once.'],
    dailyEyebrow:['03 / KIS LÉPÉSEK, BIZTOS HALADÁS','03 / SMALL STEPS, STEADY PROGRESS'],
    dailyTitle:['Egy jó nap néhány pipával kezdődik.','A good day starts with a few checkmarks.'],
    dailyIntroTitle:['A te ritmusod. A te kalandod.','Your pace. Your adventure.'],
    dailyIntro:['Ez a saját ellenőrzőlistád. Pipáld ki, amit elvégeztél, és folytasd onnan, ahol abbahagytad.','This is your personal checklist. Tick off what you have completed and pick up where you left off.'],
    whenLogin:['Belépéskor','When you log in'],
    whenLoginCopy:['Jutalmak, napi feladatok, energia és az elérhető bosspróbálkozások ellenőrzése.','Check rewards, daily tasks, energy and available boss attempts.'],
    whenLeaving:['Kilépés előtt','Before you leave'],
    whenLeavingCopy:['Tipp: nézd át a felszerelést, gyűjtsd be a jutalmakat, és ellenőrizd a háttérvadászatot.','Tip: review your equipment, collect rewards and check Background Hunt.'],
    dailySystems:['Ha már megnyílt: napi companion Feed, ingyenes dungeon keys, Guild Raid támadás és Hakmun mintáinak leadása. A Stormcatcher pihenőjét a Today’s to-do mutatja.','Once unlocked: feed your companion daily, collect free dungeon keys, make your Guild Raid attack and deliver samples to Hakmun. Today’s to-do shows when Stormcatcher is ready.'],
    dailyAvailability:['Az egyes napi rendszerek elérhetőségét és próbálkozásait mindig a játékban ellenőrizd. A listán szereplés nem jelenti, hogy minden funkció már megnyílt a karakterednek.','Always check in-game availability and attempts for each daily system. Its presence on this list does not mean every feature is already unlocked for your character.'],
    today:['A MAI KALANDOD','TODAY’S ADVENTURE'],
    checklistTitle:['Napi ellenőrzőlista','Daily checklist'],
    progressLabel:['Elvégzett napi teendők','Completed daily tasks'],
    dailyMessage:['Minden kaland egy lépéssel kezdődik.','Every adventure starts with one step.'],
    clearChecks:['Pipák törlése','Clear checkmarks'],
    storageNote:['Mentés csak ebben a böngészőben. Új lista a helyi naptár szerinti következő napon; ez nem a játék napi visszaállítása.','Saved only in this browser. A new list starts on the next local calendar day; this is not the game’s daily reset.'],
    progressEyebrow:['04 / A KÖVETKEZŐ SZINT','04 / THE NEXT LEVEL'],
    progressTitle:['Az erő a részletekben rejlik.','Strength lies in the details.'],
    cpCopy:['Kattints a HUD CP értékére az összetevőihez. A Hunt oldal sávja a térkép átlagos hőséhez mér. A tárgyon látható ▲ jel a jelenleg viseltnél jobbat mutatja.','Select the CP value in the HUD to see its components. The bar on the Hunt page compares you with the map’s average hero. The ▲ on an item marks an upgrade over your currently equipped item.'],
    cpTip:['Tipp: a CP-változásra jobban figyelj, mint önmagában a tárgy színére. A viselési szint a tárgykártyán látható.','Tip: pay more attention to the CP change than to an item’s colour alone. The required level appears on its card.'],
    rarityTitle:['Ismerd fel a ritkaságokat','Recognize item rarities'],
    rarityCopy:['Alacsonyabbtól a magasabb ritkaság felé:','From lower to higher rarity:'],
    rarityDetails:['A Heroic lila, a map boss saját Mythic tárgya arany. Magasabb ritkasággal több bónuszsor és foglalat jár. A fegyver és armour kaszthoz kötött; a többi felsorolt slot közös.','Heroic items are purple; a map boss’s Mythic item is gold. Higher rarities have more bonus lines and sockets. Weapons and armour are class-specific; the other listed slots are shared.'],
    forgeEyebrow:['A KOVÁCS MELLETT','AT THE BLACKSMITH'],
    forgeTitle:['Mielőtt lecsap a kalapács.','Before the hammer falls.'],
    forgeCopy:['Blacksmith → Upgrade. Gangdo a Chance alatt mutatja a pontos esélyt, a Cost alatt az árat. Hiányzó anyagnál a Where from? segít.','Blacksmith → Upgrade. Gangdo shows the exact chance under Chance and the price under Cost. Where from? helps you find missing materials.'],
    safeStepsCopy:['Az első, biztonságosnak jelölt lépések mindig sikerülnek. Tipp: fejleszd így minden viselt tárgyadat.','The first steps marked safe always succeed. Tip: upgrade every equipped item through these steps.'],
    riskyStepsTitle:['Kockázatos lépések','Risky upgrades'],
    riskyStepsCopy:['Védelem nélkül sikertelenségkor a tárgy és a belehelyezett Spirit Stone-ok is elégnek.','Without protection, a failed attempt destroys the item and any socketed Spirit Stones.'],
    forgeWarning:['A forrás nem ad számszerű biztonsági határt. Mindig a következő lépés Chance és Cost értékét ellenőrizd.','The source does not specify a numerical safe limit. Always check the Chance and Cost of the next step.'],
    scrollCopy:['Sikertelenségkor a tárgy megmarad, de egy fejlesztési fokozatot visszaesik.','On failure, the item is saved but loses one upgrade level.'],
    dustCopy:['Sikertelenségkor a tárgy megmarad, és a fejlesztési fokozatát is megtartja.','On failure, the item is saved and keeps its upgrade level.'],
    spiritStonesTitle:['Spirit Stone-ok','Spirit Stones'],
    spiritStonesCopy:['A bossoktól a Blacksmith → Sockets fülre kerülnek. Rare vagy jobb tárgyba ingyen illeszthetők.','Boss rewards go to Blacksmith → Sockets. They can be socketed into a Rare or better item for free.'],
    bossEyebrow:['AZ ELSŐ NAGY KIHÍVÁS','THE FIRST BIG CHALLENGE'],
    bossCopy:['A Village Outskirts első map bossa. Legyőzése megnyitja a Highwayman Country térképet. A Hunt → Boss kártyája mutatja az esélyt és a napi ingyenes próbálkozásaidat; ezek csak korlátozottan gyűlnek.','The first map boss in Village Outskirts. Defeating it unlocks Highwayman Country. The Hunt → Boss card shows your chance to win and free daily attempts; unused attempts accumulate only up to a limit.'],
    bossTipTitle:['Tipp · Készülj fel','Tip · Be prepared'],
    bossTip:['Az első győzelem biztosan ad set-darabot, Heroic tárgyat és Spirit Stone-t. Ingyenes vereség után a Momentum segíti a következő próbát.','Your first victory guarantees a set piece, a Heroic item and a Spirit Stone. After losing a free attempt, Momentum helps your next try.'],
    bossShowcaseEyebrow:['EGY PILLANTÁS A KÉSŐBBI HARCOKBA','A GLIMPSE OF LATER BATTLES'],
    bossShowcaseTitle:['Amikor a boss visszaüt.','When the boss fights back.'],
    bossShowcaseCopy:['A hivatalos Creator Kit Flamebeard elleni harcot mutat be. Nagyítsd ki a képet, és ismerd meg a harci felületet: a résztvevők, a HP és a képességek jelzéseit.','The official Creator Kit shows a battle against Flamebeard. Enlarge the image to explore the combat interface, including participant, HP and skill indicators.'],
    bossGuideLink:['Tovább a bosskalauzhoz','Continue to the boss guide'],
    galleryEyebrow:['PILLANATOK A VIHAR VILÁGÁBÓL','MOMENTS FROM THE WORLD OF THE STORM'],
    galleryTitle:['Ez a világ rád vár.','This world is waiting for you.'],
    galleryTag:['Eredeti Stonestorm-képek','Original Stonestorm images'],
    galleryIntro:['A falu főterétől a Stormcatcher tetejéig. Fedezd fel a játék hangulatát a hivatalos Creator Kit képein — kattints a részletekért.','From the village square to the top of Stormcatcher. Explore the game’s atmosphere through official Creator Kit images—click to see the details.'],
    galleryCredit:['Képek:','Images:'],
    galleryCreditCopy:['. A feloldásokat és az indulási időpontokat az útmutató megfelelő fejezetei jelzik.','. Unlocks and start dates are noted in the relevant guide chapters.'],
    sourcesTitle:['A kalauzról és a forrásokról','About this guide and its sources'],
    sourcesLead:['Nem hivatalos, rajongók által készített magyar útmutató.','An unofficial, fan-made English guide.'],
    sourcesFirst:['Elsődleges forrás: a játék hivatalos Discord-szerverének útmutatóiból összeállított, a projekt gazdája által átadott teljes TXT-dokumentum. Feldolgozva: 2026. október 31. Hivatalos weboldal:','Primary source: the complete TXT document supplied by the project owner, compiled from guides on the game’s official Discord server. Processed: October 31, 2026. Official website:'],
    sourcesFirstAfter:['. A „Tipp” szövegek ajánlások; a játékbeli elnevezéseket angolul hagytuk. A játék gyakran változik, ezért eltérésnél a frissebb hivatalos leírás és a játék felülete az irányadó.','. “Tip” text is advisory; in-game names are retained in English. The game changes frequently, so newer official information and the in-game interface take precedence when details differ.'],
    sourcesSecond:['A dokumentum szerint az App Store, Google Play és Steam változatok fejlesztés alatt állnak; a Kingdom War és Banner League 2026. november 9-én indul. Az időszakos kódokat és ajánlatokat a forrás szerinti dátumukkal jelöljük. A kalauz képei és a logó a Stonestorm hivatalos Creator Kitjéből származnak, engedéllyel használva. A magyar kalauz önálló rajongói oldal.','According to the source document, App Store, Google Play and Steam versions are in development; Kingdom War and Banner League start on November 9, 2026. Limited codes and offers are labelled with their source dates. Guide images and the logo are used with permission from the official Stonestorm Creator Kit. This is an independent fan guide.'],
    privacyTitle:['Mit tárol ez az oldal?','What does this site store?'],
    privacyCopy:['A napi lista dátumát és pipáit, a kiválasztott kasztokat, a témaszűrőt és a külön elmentett karakterbuildeket a böngésződ localStorage tárhelyén. Nincs analitika, fiók vagy adatküldés. A keresés helyben történik. A naptári nap a készüléked időzónáját követi. A böngésző tárhelyének törlésével a mentések is törölhetők; privát módban vagy file:// megnyitáskor a mentés böngészőfüggő.','The date and checkmarks for your daily list, selected classes, topic filter and separately saved character builds are stored in your browser’s localStorage. There is no analytics, account or data transmission. Searches run locally. The calendar day follows your device’s time zone. Clearing browser storage also deletes saved data; in private mode or when opened via file://, storage depends on the browser.'],
    noScript:['A fejezetek JavaScript nélkül is olvashatók. A kasztkártyákhoz, a keresőhöz, a GYIK-hez és a napi lista mentéséhez engedélyezd a JavaScriptet.','The chapters are readable without JavaScript. Enable JavaScript to use class cards, search, the FAQ and saved daily checklist.'],
    brandSubtitle:['MAGYAR KALAUZ','ENGLISH GUIDE'],
    footerTagline:['Kalandra fel. A saját tempódban.','Adventure awaits. At your own pace.'],
    officialLink:['Hivatalos Stonestorm','Official Stonestorm'],
    footerLegal:['Nem hivatalos, rajongók által készített magyar útmutató. A Stonestorm név a jogosultjához tartozik.','Unofficial, fan-made guide. The Stonestorm name belongs to its respective owner.'],
    lightboxEyebrow:['STONESTORM · KÉPNÉZŐ','STONESTORM · IMAGE VIEWER'],
    lightboxTitle:['Kép nagyítása','Enlarge image'],
    closeLightboxLabel:['Képnéző bezárása','Close image viewer'],
    fullSize:['Teljes méret','Full size'],
    closeHint:['Bezárás:','Close:'],
    imageError:['A kép nem tölthető be. Zárd be a képnézőt, majd próbáld újra.','The image could not be loaded. Close the viewer and try again.'],
    backTop:['Vissza a tetejére','Back to top']
  };
