      'pets.progression.slotsNote':'A tanulható helyek formánként: 0 / 1 / 2 / 3 / 3. Egy helyre választható képesség 1–5. szintig fejleszthető, és ugyanaz a képesség csak egy helyen szerepelhet. A signature különálló, nem foglal tanulható helyet. Egyező signature és tanult képesség esetén csak az erősebb szint érvényesül.',
      'pets.progression.observationNote':'A Mohaagancs 22-es referencia nincs megerősítve. A 35-ös érték a kliens harmadik formájának plafonja, nem bizonyítja a 22-es felnőtt küszöböt.',
