      'pets.evolution.warning':'A karakter evolveCores / evolveThread / evolveNyang mezői felülírhatják az árakat. A kliens tartalék magdarabszáma 1; a v3 költségkonfiguráció 2 maggal és 2× fonalszorzóval is számol. A spine formánként további 1 / 1,5 / 2 / 2,5 szorzókat tartalmaz. Ezekből nem következtetünk végleges szerveres árra; a játék Fejlődés ablaka az irányadó.',
