      'pets.conflict.badge':'CLIENT EVIDENCE · OBSERVATION CONFLICT',
      'pets.conflict.copy':'The active model follows the statically verified client form caps: {caps}, with a final maximum of {maxLevel}. A separate observation reports {observedCaps}, with a maximum of 50. We retain that observation but do not claim that a level-50 or level-60 cap is proven. The old level-10 rule is historical data.',
