      'pets.progression.overlap':'Level thresholds can overlap: the lower of the form cap and hero level applies. Form names come from the Hungarian client localization; active caps are recorded in the client rules in pet-system-evidence.json, with the older observation stored separately.',
      'pets.progression.slotsNote':'Learnable slots by form: 0 / 1 / 2 / 3 / 3. A skill assigned to a slot can be raised to level 1–5, and the same skill can occupy only one slot. The signature is separate and does not use a learnable slot. If a signature and learned skill match, only the stronger level applies.',
      'pets.progression.observationNote':'The Mossantler level-22 reference is not confirmed. Level 35 is the client cap for the third form; it does not prove an adult threshold at level 22.',
