      'pets.evolution.nyang':'Base nyang',
      'pets.evolution.slots':'Learnable slots',
      'pets.evolution.requirement':'Reach the current form cap and have the required core, Bond Thread and nyang. This table shows base values from v3 forms.cost; it does not guarantee the final price.',
      'pets.evolution.warning':'Character fields evolveCores / evolveThread / evolveNyang can override these costs. The client fallback uses one core; the v3 cost config also contains two cores and a 2× thread multiplier. The spine adds form multipliers of 1 / 1.5 / 2 / 2.5. We do not infer a final server price from these values; the in-game Evolution screen is authoritative.',
      'pets.skills.title':'Companion skills · levels 1–5',
