      'pets.skills.note':'These are client skill values, not the complete combat-damage formula. Skill level, companion level, form and learnable-slot count are separate concepts.',
      'pets.books.title':'Skill books and learning',
      'pets.books.copy':'Use a book to learn a skill in a free, unlocked slot on your active companion, or raise a known skill up to level 5. The same skill cannot occupy two slots; innate skills are protected separately. On replacement, the old skill book is returned to the bag according to the Hungarian client text.',
      'pets.books.dungeonPool':'Dungeon pool',
      'pets.books.catalog':'Books in the client list',
      'pets.books.chance':'The boss-chest skill-book chance parameter is {chance}; the pity parameter for clears without a book is {pity}. Pool weight is not a guaranteed drop chance, and server-side pity timing is unverified.',
      'pets.books.contentApi':'CONTENT API · CLIENT CONFIGURATION',
      'pets.books.collectionTitle':'Companion books and skill books are separate systems',
      'pets.books.collection':'The Companion Book is a species collection: each new species grants {perSpecies}, capped at {cap} per key. It is not a learnable skill or the maximum of all companion effects. Skill-book IDs use pet_book_<skill>.',
