      'pets.feeding.nyang':'Feeding nyang',
      'pets.feeding.threadHero':'Thread and hero-XP cost',
      'pets.feeding.daily':'Daily feeding',
      'pets.feeding.levelCap':'Level cap',
      'pets.feeding.nextXpValue':'{base} + {perLevel} × current companion level; the server xpToNext field takes precedence.',
      'pets.feeding.feedXpValue':'Round(XP for next level × {share}); this is the client fallback model.',
      'pets.feeding.materialValue':'{base} + {perLevel} × companion level; feedMaterials can override it.',
      'pets.feeding.nyangValue':'{perLevel} × companion level as a client fallback; feedNyang can override it.',
      'pets.feeding.threadHeroValue':'Read from the character’s feedThread and feedHeroXp fields. Raw costs.feed.thread / heroXpMult settings alone do not prove an actual cost.',
      'pets.feeding.dailyValue':'{free} free uses per day; the Hungarian help text mentions one additional daily feeding for VÉ. “Free” does not prove that material or other costs are waived.',
      'pets.feeding.capValue':'The lower of the form cap and hero level; final maximum {maxLevel}.',
      'pets.feeding.example':'Client fallback example at level 1: {materials} material, {nyang} nyang and {xp} companion XP. It does not assume a hero-XP or thread deduction; the price shown in game may override it.',
      'pets.feeding.shareTitle':'XP sharing: two configurations with different values',
