      'pets.feeding.dungeon':'Dungeon',
      'pets.feeding.petRoom':'Companion room',
      'pets.feeding.warning':'The spine contains newer companion rules as well. We do not add the two XP configurations together or treat them as a verified final server formula. Keep companion XP gained and hero XP deducted separate. The game help says feeding cannot make the hero lose a level.',
      'pets.sources.summary':'Sources, legacy configuration and reference samples',
