      'pets.sources.caps':'Static client evidence records form caps of 10/20/35/50/60. A separate observation reports 10/20/30/40/50. The snapshot contains skill, slot and XP configuration, but no form-cap field.',
      'pets.sources.references':'pets.v3.reference.bands and spine.hero.pets.reference.bands are hero/reference samples, not unlock thresholds. No source confirms a Mossantler level-22 species/form reference or explicit unlock; 35 is only the client Adult cap.',
      'pets.sources.legacy':'The old rules maximum, stages and bond levels are historical configuration. V3 scaling, API base costs and per-character costs are separate data.',
