    "game.dungeonLore.wild": "Egy öreg medve odúja a falu határán túl, ahová a környék farkasai és az útonállók földjéről jött orvvadászok egyszerre költöztek be, és azóta sem tudják eldönteni, kié a hely. A legmélyén a Mohahátú Medveúr alszik, és szerinte mindkét bérlő tartozik a lakbérrel.",
    "game.creature.d_wild_cub": "Vadonkölyök",
