    'critical.title':['Kritikus sebzés kalkulátor','Critical damage calculator'],
    'critical.chanceDefinition':['A kritikus találat valószínűsége. Maximum {cap}.','The chance of a critical hit. Maximum {cap}.'],
    'critical.damage':['Kritikus sebzés','Critical damage'],
    'critical.damageDefinition':['A kritikus ütés sebzésszorzója. Alapértéke {base}×.','The critical hit damage multiplier. Its base value is {base}×.'],
    'critical.bonusDefinition':['A szorzóhoz hozzáadódó extra érték. Konfiguráció szerinti felső korlát: +{cap}. A nyers érték soft-cap átváltása külön ellenőrzést igényel.','Extra value added to the multiplier. Configured upper limit: +{cap}. Converting the raw value through the soft cap requires separate verification.'],
    'critical.normal':['Normál sebzés','Normal damage'],
    'critical.normalHint':['Sebzésérték; például 10 000.','Damage value, for example 10,000.'],
    'critical.chanceInput':['Kritikus esély ehhez a számításhoz','Critical chance for this calculation'],
    'critical.chanceHint':['A kalkulátor az 50% feletti részt nem alkalmazza.','The calculator does not apply the amount above 50%.'],
    'critical.bonusHint':['A fegyvertáblázat választása ezt a mezőt tölti ki.','Selecting a weapon-table value fills this field.'],
    'critical.gear':['További felszerelésbónusz (opcionális)','Additional equipment bonus (optional)'],
    'critical.gearHint':['Üresen 0%. A fenti fegyverbónuszt ne számold kétszer.','Blank means 0%. Do not count the weapon bonus above twice.'],
    'critical.example':['10 000 / 50% / +40% példa','10,000 / 50% / +40% example'],
    'critical.model':['Egyszerűsített modell: a normál sebzést az 1,5 + min(max(0, összesített bónusz), 0,75) szorzóval számítjuk át. Ez nem a teljes harci sebzésképlet: védelem, kitérés, képességek és egyéb harci módosítók nélkül számol. A kijelzett eredményeket kerekítjük.','Simplified model: normal damage is multiplied by 1.5 + min(max(0, total bonus), 0.75). This is not the full combat damage formula: defence, evasion, skills and other combat modifiers are excluded. Displayed results are rounded.'],
    'critical.baseSource':['Az alapértékek forrása','Source of base values'],
    'critical.snapshot':['2026-11-06-i mentés.','Snapshot from 2026-11-06.'],
    'critical.weapons':['Fegyverek kritikus sebzésbónuszai','Weapon critical damage bonuses'],
    'critical.weaponsCopy':['Kliensadatokban szereplő alapértékek. Nem bizonyított, hogy a szerver minden esetben módosítás nélkül ezeket osztja ki. A T1–T5 adatbázisbeli fokozat, nem igazolt hivatalos ritkasági kategória.','Base values from client data. It is not proven that the server always assigns them unchanged. T1–T5 are database tiers, not verified official rarity categories.'],
    'critical.weaponLevel':['Fegyver szintje (1–60)','Weapon level (1–60)'],
    'critical.weaponHint':['Válassz szintet, majd kattints egy T1–T5 értékre. Szintváltáskor a kiválasztott fokozat bónusza automatikusan frissül. Mobilon a táblázat oldalra görgethető.','Choose a level, then select a T1–T5 value. The selected tier bonus updates automatically when the level changes. The table scrolls horizontally on mobile.'],
    'critical.weaponSourceTitle':['A fegyvertáblázat forrása és korlátai','Weapon-table source and limitations'],
    'critical.weaponSource':['2026-11-06-i klienskivonat: spine.lines.percent (a projektgazda által megadott szintsávok). Helyben egyeztetett alaptier: 02_kovacsolas_bonuses_kovek.json · stones.items.line.tiers.critDamage. A helyi tematikus kivonat nem tartalmazza a teljes magasabb szintű spine.lines.percent sávlistát.','2026-11-06 client extract: spine.lines.percent (level bands supplied by the project owner). Locally checked base tiers: 02_kovacsolas_bonuses_kovek.json · stones.items.line.tiers.critDamage. The local thematic extract does not contain the full higher-level spine.lines.percent band list.'],
    'critical.weaponCaveat':['A táblázat korábbi, nyers referencia; az új capScale alkalmazása még nem igazolt. A magasabb szintsávok számai a projektgazdai klienskivonatból származnak; a szerveroldali generálási esélyeket nem ismerjük.','This table is an older raw reference; application of the new capScale is unverified. Higher-level values come from the project owner’s client extract; server-side generation probabilities are unknown.'],
    'critical.softUnknown':['A nyers kritikus sebzésbónusz soft-cap átváltása még nem igazolt. A kalkulátor nem ad végleges sebzést; a játék Bónuszok paneljén megjelenő értéket használd ellenőrzéshez.','The raw critical damage bonus soft-cap conversion is not yet verified. The calculator does not give final damage; check the value shown in the game’s Bonuses panel.'],
