    'bonus.source.imperial.explanation':['XP +25, nyang +20, zsákmány +10 százalékpont. A VÉ-s főzetekkel közös 50 százalékpontos fizetős keretbe számít.','XP +25, Nyang +20, loot +10 percentage points. It shares the 50-point paid allowance with Storm Coin potions.'],
