    'bonus.source.sets.explanation':['Csak a külön szettbónusz; a felszerelésben már szereplő értéket ne számold kétszer.','Only the separate set bonus; do not count values already included in equipment twice.'],
    'bonus.source.temporary.explanation':['Nem VÉ-s, nem különleges erősítések. A fizetős főzetet külön sorban kezeld.','Non-Storm-Coin, non-special boosts. Enter paid potions separately.'],
    'bonus.source.equipment.source':['A játék közölt leírása: a normál bónuszok a 100%-os plafonba számítanak.','Published game description: normal bonuses count toward the 100% cap.'],
    'bonus.source.imperial.source':['Közölt játékbeli leírás és menlevélmegfigyelés; vip.bonuses magyar szöveg.','Published game description and pass observation; Hungarian vip.bonuses text.'],
    'bonus.source.potionsNyang.source':['Helyi magyar súgó: capNyang – a szokásos szorzóplafonba számít.','Local Hungarian help: capNyang counts toward the normal multiplier cap.'],
    'bonus.source.potionsCoins.source':['Közölt játékleírás; capCoins – plafon fölött, legfeljebb +50%-ig.','Published game description: capCoins applies above the cap, up to +50%.'],
    'bonus.source.normalSource':['A játék közölt összeadási szabálya: a nem különleges, nem VÉ-s bónusz a normál keretbe számít. Az összeget a karaktered adatai alapján add meg.','Published game addition rule: non-special, non-Storm-Coin bonuses count toward the normal allowance. Enter the amount from your character data.'],
    'bonus.formula':['Érvényes = min(normál összeg, 100) + min(fizetős összeg, 50). Elvesző = gyűjtött összeg − érvényes összeg. Minden érték százalékpont.','Effective = min(normal total, 100) + min(paid total, 50). Lost = collected total − effective total. All values are percentage points.'],
