    'bonus.help':['Az elméleti +150%-os felső határhoz mindkét keretet ki kell tölteni. Ez nem automatikusan járó játékosbónusz. A felszerelésen kívüli forrásokat ne számold még egyszer a felszerelés értékéhez.','The theoretical +150% maximum requires filling both allowances. It is not an automatic player bonus. Do not count non-equipment sources again as equipment.'],
