    'system.arenaMissing':['A rendszeradatok még nem állnak rendelkezésre.','System data is not yet available.'],
    'system.arenaUnknown':['Játékbeli adatmintát igényel','Requires an in-game data sample'],
    'system.arenaRulesNotice':['Két külön rangsor és szabályrendszer. A napi harci korlát és a teljes szerveroldali harci képlet továbbra is játékbeli adatmintát igényel.','Two separate rankings and rule sets. The daily fight limit and complete server-side combat formula still require in-game data samples.'],
    'system.arenaPvpNotice':['A kísérők, céh- és házhatások teljes PvP-alkalmazási köre, a pontos harci képlet és a próbálkozási limit nincs a publikus konfigurációban. Nem alkalmazzuk automatikusan a PvE-limiteket.','The full PvP application of companion, guild and house effects, the exact combat formula and the attempt limit are not in the public configuration. PvE limits are not automatically applied.'],
    'system.arenaClientNotice':['Ezek a magyar klienssúgó állításai. A tróndíj alapösszege, az egyéni potionkeret és árlista, a pontos pontozási képlet és a szerveroldali eltérések adatmintát igényelnek.','These are claims from the Hungarian client help. The base throne award, individual potion allowance and prices, exact scoring formula and server-side differences require data samples.'],
    'system.arenaEntryNotice':['A csomag egyszerre tartalmaz végleges, szezon végéig tartó és szezonkezdő 24 órás belépési szabályt. Az aktuális aktív változatot a bejelentkezett nézet adja; egyiket sem állítjuk általános jelenlegi szabálynak.','The package contains permanent, season-end and season-opening 24-hour entry rules. The logged-in view determines the active variant; none is asserted as the general current rule.'],
    'arena.title':['Aréna','Arena'],
    'arena.copy':['Két külön játékmód, külön rangsorokkal és szabályokkal. A Pure mód hivatalos magyar neve Tiszta aréna; a Bandit módé Bandita Liga.','Two distinct game modes with separate rankings and rules. Their official Hungarian names are Tiszta aréna for Pure and Bandita Liga for Bandit.'],
    'arena.pureTitle':['Tiszta aréna','Pure Arena'],
    'arena.banditTitle':['Bandita Liga','Bandit League'],
    'arena.pureLead':['Becsületbeli párbaj. Rablás nélkül.','A duel of honor. No theft.'],
    'arena.banditLead':['Létra, lopás, bosszú és trónharc.','Ladder, theft, revenge and throne battles.'],
    'arena.pureArt':['BECSÜLET ÉS PÁRBAJ','HONOR AND DUELING'],
