    'arena.rewardBand':['Ligadíj sávja','League reward bracket'],
    'arena.exactAmount':['Pontos mennyiség','Exact amount'],
    'arena.trophySection':['Bandita-trófea az Otthonban','Bandit trophies in Home'],
    'arena.trophy':['Trófea','Trophy'],
    'arena.condition':['Feltétel a klienssúgóban','Condition in client help'],
    'arena.homeLink':['Otthon, trófeák és berendezés →','Home, trophies and furniture →'],
    'arena.placeholder':['[játékbeli érték]','[in-game value]'],
    'arena.client.pureIntro':['Itt csak a szinted, a statjaid és a felszerelésed számít: a Viharszív és a főzetek nem hatnak. Csak valódi hősök ellen harcolsz, saját becsületért és saját rangsorért. Yakdo teája addig az ajtóban vár.','Only your level, stats and equipment count here: Viharszív and potions have no effect. Fight only real heroes for your own honor and ranking. Yakdo’s tea waits at the door.'],
    'arena.client.noSkip':['Itt nem lehet átugrani.','Skipping is not possible here.'],
    'arena.client.reroll':['Óránként egyszer ingyen kérhetsz új ellenfeleket. Itt Viharérméért sem lehet többet.','Request new opponents once per hour for free. Additional requests are unavailable even for Viharérme.'],
    'arena.client.reward':['A jutalom kötött cím: a hősödé marad, nem adható tovább.','The reward is a bound title: it remains with your hero and cannot be transferred.'],
    'arena.client.banditIntro':['A banditák ligája: küzdj fel magad a létrán, és foglald el a trónt!','The bandits’ league: climb the ladder and claim the throne!'],
    'arena.client.leagueTitle':['Ligák','Leagues'],
    'arena.client.league':['21. szinttől, 5 szintes ligákban (21-25, 26-30 …). Új liga 15 aktív játékostól nyílik.','From level 21, leagues cover five levels (21–25, 26–30 …). A new league opens with 15 active players.'],
    'arena.client.attackTitle':['Támadás','Attack'],
    'arena.client.attack':['Csak az előtted álló 5 játékost. Ha nyersz, helyet cseréltek. Ugyanazt óránként egyszer.','Only the five players ahead of you can be attacked. If you win, you swap places. Attack the same player once per hour.'],
    'arena.client.theftTitle':['Lopás','Theft'],
    'arena.client.theft':['Győzelemkor a vesztes be nem gyűjtött farmjának 10%-a és 1 energia a tiéd. Gyűjts be gyakran!','On victory you receive 10% of the loser’s uncollected farm and 1 energy. Collect often!'],
    'arena.client.revengeTitle':['Bosszú','Revenge'],
    'arena.client.revenge':['24 óráig a tolvajon, akkor is, ha mögötted áll. Ha nyersz, az ellopott rész fele is visszajár.','For 24 hours you can attack the thief even if they are behind you. If you win, half the stolen amount is returned.'],
    'arena.client.throneTitle':['Trón és kassza','Throne and treasury'],
    'arena.client.throne':['Az 1. hely a bajnok, a kasszája óránként nő. Aki legyőzi, viszi; 24 óra kitartás után a bajnoké. A támadás díjas, aznap minden újabb másfélszer drágább. 12 és 24 óra tartás után a bajnok olyan tárgyat is kap, amit mások ellophatnak, 24 óránál pedig a liga bajnoki címét. Aki zsinórban több kört tart, körről körre kisebb részét kapja a kasszának; aki elveszi tőle a trónt, a teljes kasszát viszi. A zsinórban tartó bajnok el is fárad: a trónharcot kevesebb élettel kezdi.','First place is the champion; the treasury grows hourly. Whoever defeats the champion takes it; after holding the throne for 24 hours the champion receives it. Attacks cost a fee, with each subsequent attack that day costing 1.5 times more. After 12 and 24 hours the champion also receives an item others can steal, and after 24 hours the league champion title. A champion holding consecutive rounds receives a smaller share each round; a challenger taking the throne receives the whole treasury. A consecutive champion also tires and starts throne battles with less health.'],
    'arena.client.prize':['A szezon végén a ligád végső helyezése szerint díj jár; a felső 10% és 25% határa a liga létszámától függ. Feltétel: legalább {{min}} Bandita-harc a szezonban (a védekezés is számít). A pet-pont csak kikelt petnél jár.','At season end rewards depend on your final league placement; the top 10% and 25% thresholds depend on league size. At least {{min}} Bandit fights are required that season (defenses count). Pet points apply only to a hatched pet.'],
    'arena.client.hpTitle':['Élet és poti','Health and potion'],
    'arena.client.hp':['Harc után 10 percenként +10%. 10% alatt nincs támadás. Az Aréna poti azonnal feltölt.','After combat, +10% every 10 minutes. You cannot attack below 10%. The Arena potion restores health immediately.'],
    'arena.client.honorTitle':['Becsület','Honor'],
    'arena.client.honor':['A becsület és a szezon marad. 7 nap távollét után kiesel a létráról.','Honor and the season remain. After 7 days away you fall off the ladder.'],
    'arena.client.pet':['Teljesítsd a szezon Aréna küldetéssorát, és a szezon végén kikel neked. Csak az Arénában vívott harcokkal fejlődik.','Complete the season’s Arena questline and it hatches at season end. It progresses only through Arena fights.'],
