    'sync.reason.schema':['Az engedélyezett séma teljes forráság-hashe és minden érintett API-mező beépített értéke egyezik. Az Atlas hozzáadott szerkesztői metaadata külön mező; az import nem szerveres végszabály-igazolás.','The allowed schema’s full source-branch hash and all affected embedded API values match. Atlas editorial metadata is separate; import does not verify final server rules.'],
    'sync.reason.historical':['Történeti érték: az újabb érték tényleges, hash-sel és mezőegyezéssel igazolt importja felülírta. A korábbi értéket nem állítjuk újonnan importáltnak.','Historical value: superseded by a newer value imported and verified by hash and field match. The earlier value is not claimed as a new import.'],
    'sync.reason.rooms':['A teljes kazamataséma és minden kapcsolat valid; az Atlas a megfelelő terem API-értékét tartalmazza.','The entire dungeon schema and all connections are valid; Atlas contains the corresponding room API value.'],
    'sync.reason.recommended':['Az eg?sz aj?nlott szint egyezik a valid?lt kazamata aktu?lis API-?rt?k?vel.','The integer recommended level matches the validated dungeon’s current API value.'],
    'sync.reason.dungeon':['A korábban elutasított kazamata teljes rekordja, minden terem és az ajánlott szint validált és pontosan egyezik az Atlasban.','The previously rejected dungeon record, all rooms and recommended level are validated and match Atlas exactly.'],
    'sync.reason.home':['Az Otthon/Aréna ismert API-mezője egyezik a forrással; a kapcsoló nem bizonyít további játékszabályt.','The known Home/Arena API field matches the source; the flag does not prove any further game rule.'],
    'sync.reason.editorial':['Szerkesztett, számított Atlas-mező: (1 − utazási szorzó) × 100. A nyers API-ból való hiánya nem adattörlés.','Editorial calculated Atlas field: (1 − travel multiplier) × 100. Its absence from the raw API is not data deletion.'],
    'sync.reason.alias':['A teljes API-ág pontosan egyezik a már mentett, más néven tárolt forrásadattal; nem új mechanika.','The full API branch matches saved source data under another name; it is not a new mechanic.'],
    'sync.reason.match':['Az ismert séma valid és az Atlas értéke igazoltan megegyezik a nyilvános API-val.','The known schema is valid and the Atlas value is verified to match the public API.'],
